"""Reference-integrity checker for FHIR-like Bundles (synthetic data only).

A Bundle looks like:
    {"resourceType": "Bundle", "entry": [{"resource": <resource>}, ...]}

Each resource has "resourceType" and "id". Observations carry
"subject.reference": "Patient/<id>"; Encounters carry "subject.reference"
plus an optional "partOf.reference": "Encounter/<id>".

check(bundle) reports:
  - dangling references (target type/id not present in the bundle)
  - duplicate ids within a resource type
  - partOf cycles among Encounters (DFS, cycle path reported)
"""

from collections import defaultdict

REF_SEPARATOR = "/"


def _parse_reference(reference):
    """Split "Patient/123" -> ("Patient", "123"); None if malformed."""
    if not isinstance(reference, str) or REF_SEPARATOR not in reference:
        return None
    ref_type, _, ref_id = reference.partition(REF_SEPARATOR)
    if not ref_type or not ref_id:
        return None
    return ref_type, ref_id


def check(bundle):
    """Return a list of finding dicts for the given bundle.

    Finding shapes:
      {"type": "dangling-reference",
       "source": "<ResourceType>/<id>",
       "field": "subject.reference" | "partOf.reference",
       "reference": "<TargetType>/<targetId>"}
      {"type": "duplicate-id", "resourceType": <type>, "id": <id>}
      {"type": "partOf-cycle", "cycle": ["Encounter/a", "Encounter/b", ...]}
    """
    entries = bundle.get("entry", []) if isinstance(bundle, dict) else []
    resources = [
        e["resource"] for e in entries
        if isinstance(e, dict) and isinstance(e.get("resource"), dict)
    ]

    # Index existing resources by (resourceType, id).
    existing = set()
    seen_ids = defaultdict(list)
    for res in resources:
        rtype = res.get("resourceType")
        rid = res.get("id")
        if rtype is None or rid is None:
            continue
        existing.add((rtype, str(rid)))
        seen_ids[(rtype, str(rid))].append(res)

    findings = []

    # --- duplicate ids within a type -------------------------------------
    reported_duplicates = set()
    for res in resources:
        rtype, rid = res.get("resourceType"), res.get("id")
        if rtype is None or rid is None:
            continue
        key = (rtype, str(rid))
        if len(seen_ids[key]) > 1 and key not in reported_duplicates:
            reported_duplicates.add(key)
            findings.append(
                {"type": "duplicate-id", "resourceType": rtype, "id": rid}
            )

    # --- dangling references ---------------------------------------------
    def walk(node, source_label, field_name):
        """Collect references from subject.reference / partOf.reference."""
        if isinstance(node, dict):
            for field in ("subject", "partOf"):
                ref_obj = node.get(field)
                if isinstance(ref_obj, dict) and "reference" in ref_obj:
                    parsed = _parse_reference(ref_obj["reference"])
                    if parsed is not None and parsed not in existing:
                        findings.append({
                            "type": "dangling-reference",
                            "source": source_label,
                            "field": f"{field}.reference",
                            "reference": ref_obj["reference"],
                        })
        elif isinstance(node, list):
            for item in node:
                walk(item, source_label, field_name)

    for res in resources:
        rtype, rid = res.get("resourceType"), res.get("id")
        if rtype is None or rid is None:
            continue
        walk(res, f"{rtype}/{rid}", None)

    # --- partOf cycles among Encounters (iterative DFS with colors) ------
    encounters = {
        str(res.get("id")): res
        for res in resources
        if res.get("resourceType") == "Encounter" and res.get("id") is not None
    }
    part_of = {}
    for eid, enc in encounters.items():
        ref_obj = enc.get("partOf")
        parsed = (
            _parse_reference(ref_obj.get("reference"))
            if isinstance(ref_obj, dict) else None
        )
        # Only edges that stay inside the Encounter set form cycles.
        part_of[eid] = parsed[1] if parsed and parsed[0] == "Encounter" and parsed[1] in encounters else None

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {eid: WHITE for eid in encounters}
    parent = {}
    cycles = []

    def report_cycle(start):
        path, node = [], start
        while node is not None:
            path.append(f"Encounter/{node}")
            node = parent.get(node)
            if node == start:
                break
        path.append(f"Encounter/{start}")
        path.reverse()  # start -> ... -> start
        return path

    for root in sorted(encounters):
        if color[root] != WHITE:
            continue
        stack = [(root, iter([part_of[root]]))]
        color[root] = GRAY
        while stack:
            node, children = stack[-1]
            advanced = False
            for child in children:
                child = child() if callable(child) else child
                if child is None:
                    continue
                if color[child] == WHITE:
                    color[child] = GRAY
                    parent[child] = node
                    stack.append((child, iter([part_of[child]])))
                    advanced = True
                    break
                if color[child] == GRAY:
                    parent[child] = node
                    cycles.append(report_cycle(child))
                    advanced = True
                    break
            if not advanced:
                color[node] = BLACK
                stack.pop()

    findings.extend({"type": "partOf-cycle", "cycle": c} for c in cycles)
    return findings


def has_findings(findings):
    return bool(findings)


def main(argv=None):
    import json
    import sys

    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        print("usage: python bundle_check.py file.json", file=sys.stderr)
        return 2
    try:
        with open(argv[0], "r", encoding="utf-8") as fh:
            bundle = json.load(fh)
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    findings = check(bundle)
    if not findings:
        print("OK: no findings")
        return 0

    for f in sorted((json.dumps(f, sort_keys=True) for f in findings)):
        print(f)
    print(f"{len(findings)} finding(s)", file=sys.stderr)
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

