"""Tests for bundle_check.check — synthetic fixtures only, no PHI."""

import copy

from bundle_check import check

# ---------------------------------------------------------------------------
# Synthetic fixtures
# ---------------------------------------------------------------------------

CLEAN_BUNDLE = {
    "resourceType": "Bundle",
    "entry": [
        {"resource": {"resourceType": "Patient", "id": "p1"}},
        {"resource": {"resourceType": "Patient", "id": "p2"}},
        {"resource": {
            "resourceType": "Encounter", "id": "e1",
            "subject": {"reference": "Patient/p1"},
        }},
        {"resource": {
            "resourceType": "Encounter", "id": "e2",
            "subject": {"reference": "Patient/p2"},
            "partOf": {"reference": "Encounter/e1"},
        }},
        {"resource": {
            "resourceType": "Observation", "id": "o1",
            "subject": {"reference": "Patient/p1"},
        }},
        {"resource": {
            "resourceType": "Observation", "id": "o2",
            "subject": {"reference": "Patient/p2"},
        }},
    ],
}

# 2 dangling refs + duplicate Patient id "p1".
BROKEN_BUNDLE = {
    "resourceType": "Bundle",
    "entry": [
        {"resource": {"resourceType": "Patient", "id": "p1"}},
        {"resource": {"resourceType": "Patient", "id": "p1"}},  # duplicate id
        {"resource": {
            "resourceType": "Observation", "id": "o1",
            "subject": {"reference": "Patient/p9"},           # dangling
        }},
        {"resource": {
            "resourceType": "Encounter", "id": "e1",
            "subject": {"reference": "Patient/p8"},           # dangling
            "partOf": {"reference": "Encounter/eX"},          # dangling too
        }},
    ],
}

# 3-encounter partOf cycle: eA -> eB -> eC -> eA.
CYCLE_BUNDLE = {
    "resourceType": "Bundle",
    "entry": [
        {"resource": {"resourceType": "Patient", "id": "p1"}},
        {"resource": {
            "resourceType": "Encounter", "id": "eA",
            "subject": {"reference": "Patient/p1"},
            "partOf": {"reference": "Encounter/eB"},
        }},
        {"resource": {
            "resourceType": "Encounter", "id": "eB",
            "subject": {"reference": "Patient/p1"},
            "partOf": {"reference": "Encounter/eC"},
        }},
        {"resource": {
            "resourceType": "Encounter", "id": "eC",
            "subject": {"reference": "Patient/p1"},
            "partOf": {"reference": "Encounter/eA"},
        }},
    ],
}

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def assert_findings_equal(actual, expected):
    """Order-independent comparison of exact findings."""
    keyed = lambda fs: sorted(map(lambda f: repr(f), fs))
    assert keyed(actual) == keyed(expected), (
        f"\nactual:   {sorted(map(str, actual))}"
        f"\nexpected: {sorted(map(str, expected))}"
    )


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------


def test_clean_bundle_has_no_findings():
    assert check(copy.deepcopy(CLEAN_BUNDLE)) == []


def test_broken_bundle_dangling_refs_and_duplicate_id():
    findings = check(BROKEN_BUNDLE)
    expected = [
        {
            "type": "dangling-reference",
            "source": "Observation/o1",
            "field": "subject.reference",
            "reference": "Patient/p9",
        },
        {
            "type": "dangling-reference",
            "source": "Encounter/e1",
            "field": "subject.reference",
            "reference": "Patient/p8",
        },
        {
            "type": "dangling-reference",
            "source": "Encounter/e1",
            "field": "partOf.reference",
            "reference": "Encounter/eX",
        },
        {"type": "duplicate-id", "resourceType": "Patient", "id": "p1"},
    ]
    assert_findings_equal(findings, expected)


def test_cycle_bundle_reports_three_encounter_cycle():
    findings = check(CYCLE_BUNDLE)
    cycles = [f for f in findings if f["type"] == "partOf-cycle"]
    assert len(cycles) == 1
    cycle = cycles[0]["cycle"]
    # Closed walk; rotate so it starts at eA regardless of DFS entry point.
    start = cycle.index("Encounter/eA")
    rotated = cycle[start:-1] + cycle[start:]
    assert rotated == ["Encounter/eA", "Encounter/eB", "Encounter/eC", "Encounter/eA"]
    # No other findings besides the cycle.
    assert all(f["type"] == "partOf-cycle" for f in findings)


def test_self_reference_cycle():
    bundle = {
        "resourceType": "Bundle",
        "entry": [{"resource": {
            "resourceType": "Encounter", "id": "solo",
            "subject": {"reference": "Patient/p1"},
            "partOf": {"reference": "Encounter/solo"},
        }}],
    }
    findings = check(bundle)
    assert {"type": "partOf-cycle", "cycle": ["Encounter/solo", "Encounter/solo"]} in findings


def test_empty_bundle():
    assert check({"resourceType": "Bundle", "entry": []}) == []

